use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl Integer { pub fn int_ty_str (self) -> & 'static str { use Integer :: * ; match self { I8 => "i8" , I16 => "i16" , I32 => "i32" , I64 => "i64" , I128 => "i128" , } } pub fn uint_ty_str (self) -> & 'static str { use Integer :: * ; match self { I8 => "u8" , I16 => "u16" , I32 => "u32" , I64 => "u64" , I128 => "u128" , } } # [inline] pub fn size (self) -> Size { use Integer :: * ; match self { I8 => Size :: from_bytes (1) , I16 => Size :: from_bytes (2) , I32 => Size :: from_bytes (4) , I64 => Size :: from_bytes (8) , I128 => Size :: from_bytes (16) , } } # [doc = " Gets the Integer type from an IntegerType."] pub fn from_attr < C : HasDataLayout > (cx : & C , ity : IntegerType) -> Integer { let dl = cx . data_layout () ; match ity { IntegerType :: Pointer (_) => dl . ptr_sized_integer () , IntegerType :: Fixed (x , _) => x , } } pub fn align < C : HasDataLayout > (self , cx : & C) -> AbiAlign { use Integer :: * ; let dl = cx . data_layout () ; AbiAlign :: new (match self { I8 => dl . i8_align , I16 => dl . i16_align , I32 => dl . i32_align , I64 => dl . i64_align , I128 => dl . i128_align , }) } # [doc = " Returns the largest signed value that can be represented by this Integer."] # [inline] pub fn signed_max (self) -> i128 { use Integer :: * ; match self { I8 => i8 :: MAX as i128 , I16 => i16 :: MAX as i128 , I32 => i32 :: MAX as i128 , I64 => i64 :: MAX as i128 , I128 => i128 :: MAX , } } # [doc = " Returns the smallest signed value that can be represented by this Integer."] # [inline] pub fn signed_min (self) -> i128 { use Integer :: * ; match self { I8 => i8 :: MIN as i128 , I16 => i16 :: MIN as i128 , I32 => i32 :: MIN as i128 , I64 => i64 :: MIN as i128 , I128 => i128 :: MIN , } } # [doc = " Finds the smallest Integer type which can represent the signed value."] # [inline] pub fn fit_signed (x : i128) -> Integer { use Integer :: * ; match x { - 0x0000_0000_0000_0080 ..= 0x0000_0000_0000_007f => I8 , - 0x0000_0000_0000_8000 ..= 0x0000_0000_0000_7fff => I16 , - 0x0000_0000_8000_0000 ..= 0x0000_0000_7fff_ffff => I32 , - 0x8000_0000_0000_0000 ..= 0x7fff_ffff_ffff_ffff => I64 , _ => I128 , } } # [doc = " Finds the smallest Integer type which can represent the unsigned value."] # [inline] pub fn fit_unsigned (x : u128) -> Integer { use Integer :: * ; match x { 0 ..= 0x0000_0000_0000_00ff => I8 , 0 ..= 0x0000_0000_0000_ffff => I16 , 0 ..= 0x0000_0000_ffff_ffff => I32 , 0 ..= 0xffff_ffff_ffff_ffff => I64 , _ => I128 , } } # [doc = " Finds the smallest integer with the given alignment."] pub fn for_align < C : HasDataLayout > (cx : & C , wanted : Align) -> Option < Integer > { use Integer :: * ; let dl = cx . data_layout () ; [I8 , I16 , I32 , I64 , I128] . into_iter () . find (| & candidate | { wanted == candidate . align (dl) . abi && wanted . bytes () == candidate . size () . bytes () }) } # [doc = " Find the largest integer with the given alignment or less."] pub fn approximate_align < C : HasDataLayout > (cx : & C , wanted : Align) -> Integer { use Integer :: * ; let dl = cx . data_layout () ; for candidate in [I64 , I32 , I16] { if wanted >= candidate . align (dl) . abi && wanted . bytes () >= candidate . size () . bytes () { return candidate ; } } I8 } # [inline] pub fn from_size (size : Size) -> Result < Self , String > { match size . bits () { 8 => Ok (Integer :: I8) , 16 => Ok (Integer :: I16) , 32 => Ok (Integer :: I32) , 64 => Ok (Integer :: I64) , 128 => Ok (Integer :: I128) , _ => Err (format ! ("rust does not support integers with {} bits" , size . bits ())) , } } }